const glyph={layers:'m12 3 10 5-10 5L2 8zM2 12l10 5 10-5M2 16l10 5 10-5',work:'M4 7h16v14H4zM8 7V3h8v4M4 12h16',model:'M3 3h6v6H3zM15 15h6v6h-6zM6 9v9h9',shield:'m12 3 8 3v6c0 5-8 9-8 9s-8-4-8-9V6zM8 12l3 3 5-6',file:'M5 3h9l5 5v13H5zM14 3v6h5M8 13h8m-8 4h6',spark:'m12 2 3 7 7 3-7 3-3 7-3-7-7-3 7-3z',book:'M3 4h7l2 2 2-2h7v15h-7l-2 2-2-2H3zM12 6v15',cursor:'m5 3 14 10-7 1-3 7z',lock:'M5 10h14v11H5zM8 10V7a4 4 0 0 1 8 0v3',plus:'M12 5v14M5 12h14',arrow:'M4 12h16m-6-6 6 6-6 6',edit:'m4 16 12-12 4 4L8 20H4v-4zM14 6l4 4',close:'m6 6 12 12M6 18 18 6',menu:'M4 6h16M4 12h16M4 18h16',play:'m8 4 12 8-12 8z',pause:'M8 4v16M16 4v16'};
const icon=n=>`<svg viewBox="0 0 24 24" aria-hidden="true"><path d="${glyph[n]||glyph.file}"/></svg>`,button=(action,label,style='',attrs='')=>`<button type="button" class="r-btn ${style}" data-q-action="${action}" ${attrs}>${label}</button>`;
const params=new URLSearchParams(location.search),store=createProjectStore();
const ui={chapter:params.get('chapter')==='3'?3:2,tab:['work','model','validate','output'].includes(params.get('tab'))?params.get('tab'):'work',section:'intake',selected:params.get('driver')||null,node:null,query:'',category:'all',focus:true,tradeoffs:true,layers:readPerspectives(2,['outcome','requirement','driver','responsibility']),flow:false,cursor:cursorPreference(),wide:false,menu:false,filter:'gaps',compare:[],compareView:'scenario',ghost:null,busy:false,dirty:false,modal:null,step:0,lastFocus:null};
