function toast(text){$('#toast').textContent=text;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),4000)}
function route(){savePerspectives(2,ui.layers);const p=new URLSearchParams({chapter:String(ui.chapter)});if(ui.chapter===2)p.set('tab',ui.tab);if(ui.selected)p.set('driver',ui.selected);history.replaceState({},'',projectURL(location.pathname+'?'+p))}
async function load(){hideTip();$('#app').innerHTML='<main class="r-loading"><p class="r-kicker">AIW V5 / Private project</p><h1>Opening quality drivers.</h1><p>Opening the saved project…</p></main>';try{project=(await store.load()).document;if(!selected())ui.selected=orderedDrivers(project)[0]?.id||null;ui.compare=orderedDrivers(project).slice(0,2).map(d=>d.id);ui.section=project.quality.intake?'scenarios':'intake';render()}catch(e){$('#app').innerHTML=`<main class="r-loading"><h1>Your project is unavailable.</h1><p>${esc(e.message)}</p>${button('reload','Try again','primary')}</main>`}}
async function send(type,payload={},message='Quality drivers saved.'){
  if(ui.busy)return false;ui.busy=true;$('#q-save-state').textContent='Saving…';$('.r-dialog')?.querySelectorAll('button[type=submit]').forEach(b=>b.disabled=true);
  try{const result=await store.command({type,payload});project=result.document;if(result.selected)ui.selected=result.selected;if(!selected())ui.selected=orderedDrivers(project)[0]?.id||null;if(type==='quality.driver'){ui.ghost=null;ui.node=null;if(ui.tab==='work')ui.section='scenarios'}ui.dirty=false;closeDialog(true);render();toast(message);return true}
  catch(e){$('#q-save-state').textContent='Not saved';const el=$('#q-form-error')||$('#q-page-error');if(el){el.hidden=false;el.innerHTML=esc(e.message)+(e.conflict?' '+button('refresh-conflict','Load latest project'):'')}toast('Your input is preserved. Review the message and save again.');return false}
  finally{ui.busy=false;$('.r-dialog')?.querySelectorAll('button[type=submit]').forEach(b=>b.disabled=false)}
}
function render(){const restoreFocus=rememberRailFocus();document.body.dataset.workspaceTab=ui.tab;hideTip();route();const ms=qualityMilestones(project),done=ms.filter(m=>m.done).length,pct=Math.round(done/ms.length*100),next=ms.find(m=>!m.done)||{name:'Open Chapter 3 decisions',id:'handoff'};
  $('#app').innerHTML=`<header class="r-topbar"><a class="r-brand" href="/?chapter=1" aria-label="AIW home"><span>${icon('layers')}</span><b>aiw</b><sup>V5</sup></a><span class="r-brand-caption">Intelligent Architecture Workbench</span><div class="r-top-status"><span id="q-save-state" role="status">Saved to your private project</span><span class="r-private">${icon('lock')}Private workspace</span></div>${button('menu',icon('menu'),'r-mobile-menu','aria-label="Toggle chapter navigation" aria-expanded="'+ui.menu+'"')}</header>
  <div class="r-shell"><aside class="r-sidebar ${ui.menu?'open':''}" aria-label="Project navigation"><p class="r-kicker">Your reference project</p><div class="r-project"><strong>Bank Payment Journey</strong><small>Requirements ${project.contentVersion} · Quality ${project.quality.version}</small></div><p class="r-kicker">Architecture journey</p><nav>${[[1,'Requirements','Trace the required behaviour'],[2,'Quality drivers','Set measurable expectations'],[3,'Decisions','Compare and record choices'],[4,'Logical application','Explore responsibilities'],[5,'Application realisation','Explore implementations'],[6,'Logical technology','Define supporting capabilities'],[7,'Technology realization','Compare and record technology choices'],[8,'Interfaces & Data','Define contracts and data ownership'],[9,'Security','Design controls and review risk'],[10,'Deployment / Runtime','Place and operate the architecture'],[11,'Review & Realize','Review the design and prepare delivery']].map(([n,title,sub])=>n<=11?`<a class="r-chapter ${ui.chapter===n?'current':''}" href="/?chapter=${n}" aria-current="${ui.chapter===n?'step':'false'}"><span>${String(n).padStart(2,'0')}</span><span><b>${title}</b><small>${sub}</small></span></a>`:`<div class="r-chapter unavailable"><span>06</span><span><b>${title}</b><small>${sub}</small></span></div>`).join('')}</nav>${explorationRail(chapterPerspectives[2],ui.layers,'data-q-layer','data-q-layers-all',2)}<div class="r-side-progress"><p class="r-kicker">Chapter 2 readiness</p>${ms.map(m=>`<button class="r-milestone" data-q-milestone="${m.id}"><span>${m.done?'✓':'○'}</span><span class="r-milestone-copy">${m.name}<small>${esc(m.detail)}</small></span></button>`).join('')}</div><p class="r-side-note">Requirements → quality → decisions.<br>One project, a continuous trail.</p></aside>
  <main id="workspace" class="r-main"><div class="r-heading"><div><p class="r-breadcrumb">Bank Payment Journey <span>/</span> Chapter ${String(ui.chapter).padStart(2,'0')}</p><h1>${ui.chapter===3?'The drivers behind your decisions.':{work:'Make quality an explicit choice.',model:'See what each target asks of the design.',validate:'Test the clarity of your expectations.',output:'A prioritised brief for architectural decisions.'}[ui.tab]}</h1><p>${ui.chapter===3?'Chapter 3 intake · Stable quality-driver references':'Quality drivers · Measurable scenarios, evidence, and trade-offs'}</p></div><div class="r-progress"><div><span>Chapter 2 readiness</span><b>${pct}%</b></div><div class="r-progress-track" role="progressbar" aria-label="Chapter 2 readiness" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${pct}"><i style="width:${pct}%"></i></div><small>${done} of 6 milestones · Includes target confirmation</small></div></div>
  <div class="r-workspace-bar">${ui.chapter===2?`<nav class="r-tabs" aria-label="Chapter surfaces">${[['work','Work','work'],['model','Model','model'],['validate','Validate','shield'],['output','Output','file']].map(([id,name,ic])=>`<button data-q-tab="${id}" class="${ui.tab===id?'active':''}" aria-current="${ui.tab===id?'page':'false'}">${icon(ic)}${name}</button>`).join('')}</nav>`:'<span class="r-intake-label">Chapter 03 / Quality-driver intake</span>'}<div class="r-where"><span>Ch. ${String(ui.chapter).padStart(2,'0')} / ${ui.chapter===3?'Intake':ui.tab[0].toUpperCase()+ui.tab.slice(1)}</span><strong>${pct}%</strong>${button('next','Next: '+esc(next.name)+icon('arrow'),'next-button')}</div></div><div id="q-page-error" class="r-error" role="alert" hidden></div>
  ${ui.chapter===3?chapter3():`<div class="r-assistant-bar"><div><span class="r-kicker">Chapter 02 / ${ui.tab}</span><span>${selected()?esc(selected().id+' · '+qualityType(selected().category).name):'Project context'}</span></div><nav aria-label="Contextual assistance">${button('sol',icon('spark')+'Sol')}${button('mind',icon('book')+'Mind Factory')}${button('cursor',icon('cursor')+'Cursor','','aria-pressed="'+ui.cursor+'"')}</nav></div><div class="r-studio ${ui.wide?'r-wide':''}"><section class="r-surface" aria-label="${ui.tab} workspace">${ui.tab==='work'?work():ui.tab==='model'?model():ui.tab==='validate'?validation():output()}</section><aside class="r-inspector" id="q-inspector" aria-label="Quality driver inspector" tabindex="-1">${inspector()}</aside></div>`}
  <footer class="r-footer"><span>AIW V5 · Confirm proposed targets against project evidence.</span><button data-q-action="about">Rule-based guidance · About this chapter</button></footer></main></div><div id="q-dialog-host"></div>`;
  if(ui.chapter===2&&ui.tab==='model'){drawMap();const strip=$('.q-driver-strip'),item=strip?.querySelector('[aria-pressed=true]');if(item)strip.scrollLeft=Math.max(0,item.offsetLeft-strip.offsetLeft-strip.clientWidth/2+item.offsetWidth/2)}
refineWorkspace(ui.tab,{chapter:2,id:ui.node?.split(':')[1]||ui.selected});restoreFocus();
}
function work(){return `<div class="r-section-tabs" aria-label="Quality work stages">${[['intake','Inputs'],['scenarios','Scenarios'],['priorities','Priority'],['compare','Compare'],['conflicts','Conflicts']].map(([id,label])=>`<button data-q-section="${id}" aria-pressed="${ui.section===id}">${label}</button>`).join('')}</div>${ui.section==='intake'?intake():['priorities','compare','conflicts'].includes(ui.section)?comparison():register()}`}
function intake(){const records=reqs(),reviewed=project.quality.intake?.sourceVersion===project.contentVersion;return `<article class="r-card"><div class="r-card-head"><div><p class="r-kicker">Chapter 1 → Chapter 2</p><h2>Start from the required behaviour.</h2></div>${button('review-intake',reviewed?'Review recorded':'Mark requirements reviewed','primary')}</div><p class="r-intro">${records.length} requirements carry their existing IDs, owners, evidence, and acceptance criteria into this chapter.</p><div class="q-intake-summary"><span><b>${records.filter(a=>a.confirmed).length}/${records.length}</b>Requirements confirmed</span><span><b>${project.quality.drivers.length}</b>Quality scenarios</span><span><b>${project.quality.drivers.filter(d=>!d.targetConfirmed).length}</b>Target assumptions</span></div><div class="r-reference-note">Example scenarios and numerical targets require review against the current requirements before confirmation.</div><div class="q-source-list">${records.map(a=>{const ds=project.quality.drivers.filter(d=>d.requirementIds.includes(a.id));return `<details><summary><span><small>${a.id} · ${a.owner?esc(a.owner):'Owner missing'}</small><strong>${esc(a.title)}</strong></span><span class="r-badge ${a.confirmed?'confirmed':'reference'}">${a.confirmed?'Confirmed':'Unconfirmed'}</span></summary><p>${esc(a.description)}</p><p><b>Acceptance</b><br>${esc(a.acceptance||'Not recorded in Chapter 1.')}</p><div class="q-linked-pills">${ds.map(d=>`<button data-q-select="${d.id}">${d.id} · ${esc(qualityType(d.category).name)}</button>`).join('')||'<span>No quality scenario linked yet.</span>'}</div><div class="r-actions"><button class="r-btn" data-q-from-requirement="${a.id}">Add a linked scenario</button><a class="r-btn" href="/?chapter=1&tab=work&artefact=${a.id}">Open source requirement ${icon('arrow')}</a></div></details>`}).join('')||'<div class="r-empty"><h3>No requirements yet.</h3><a class="r-btn" href="/?chapter=1">Open Chapter 1</a></div>'}</div></article>`}
function filtered(){return orderedDrivers(project).filter(d=>(ui.category==='all'||d.category===ui.category)&&(!ui.query||[d.id,d.scenarioId,d.title,d.owner,d.metric].join(' ').toLowerCase().includes(ui.query.toLowerCase())))}
function register(){return `<article class="r-card"><div class="r-card-head"><div><p class="r-kicker">One driver / One quality scenario</p><h2>The quality-driver register</h2></div>${button('add',icon('plus')+'Add scenario','primary')}</div><div class="q-register-tools"><label><span class="r-sr-only">Find a quality driver</span><input id="q-search" type="search" placeholder="Find an ID, driver, or owner…" value="${esc(ui.query)}"></label><label><span class="r-sr-only">Filter quality concern</span><select id="q-category"><option value="all">All quality concerns</option>${QUALITY_TYPES.map(t=>`<option value="${t.id}" ${ui.category===t.id?'selected':''}>${t.name}</option>`).join('')}</select></label></div><p class="r-note">Ordered by named priority, then your chosen order within that priority.</p><div id="q-driver-list">${driverList()}</div></article>`}
function driverList(){const all=orderedDrivers(project);return filtered().map(d=>`<article class="q-driver-row ${ui.selected===d.id?'selected':''}"><button class="q-driver-main" data-q-select="${d.id}" data-q-insight="driver:${d.id}"><span class="q-driver-meta"><i style="background:${qualityType(d.category).color}"></i>${d.id} / ${d.scenarioId} · ${qualityType(d.category).name}</span><h3>${esc(d.title)}</h3><p>${esc(d.metric||'Metric not defined')} <strong>${esc(targetText(d))}</strong></p><small>${d.requirementIds.length} requirements · ${d.responsibilityIds.length} responsibilities</small></button><div class="q-driver-row-actions"><span class="q-priority">${d.priority} · ${all.indexOf(d)+1}</span>${targetBadge(d)}<button class="r-btn" data-q-edit="${d.id}" aria-label="Edit ${d.id}">${icon('edit')}Edit</button></div></article>`).join('')||'<div class="r-empty"><h3>No scenarios in this view.</h3><p>Choose another concern or add a scenario.</p></div>'}
function comparison(){const ordered=orderedDrivers(project),a=driver(ui.compare[0]),b=driver(ui.compare[1]);
 const title=ui.section==='priorities'?'Set the priority order':ui.section==='conflicts'?'Resolve competing expectations':'Compare two quality drivers';
 const body=ui.section==='priorities'?`<p class="r-intro">Critical protects a non-negotiable outcome. Important materially affects the service. Supporting improves the experience. Each priority needs a reason.</p><div class="q-priority-list">${ordered.map(d=>{const group=ordered.filter(x=>x.priority===d.priority),i=group.indexOf(d);return `<div><span class="q-order">${ordered.indexOf(d)+1}</span><button data-q-select="${d.id}"><small>${d.id} · ${d.priority}</small><b>${esc(d.title)}</b><span>${esc(d.rationale||'Priority reason missing')}</span></button><div><button class="r-btn" data-q-move="${d.id}" data-direction="up" aria-label="Move ${d.id} up within ${d.priority}" ${i===0?'disabled':''}>↑</button><button class="r-btn" data-q-move="${d.id}" data-direction="down" aria-label="Move ${d.id} down within ${d.priority}" ${i===group.length-1?'disabled':''}>↓</button><button class="r-btn" data-q-edit="${d.id}" aria-label="Edit priority for ${d.id}">Edit</button></div></div>`}).join('')}</div>`:ui.section==='conflicts'?`<h3>Recorded conflicts</h3>${conflictList()}<details class="f-disclosure"><summary>Explore potential trade-offs · ${potentialTradeoffs(project,null).length}</summary><p class="r-note">These are prompts for review. A conflict is recorded only when you choose to record one.</p><div class="f-tradeoffs">${tradeoffList(null)}</div></details>`:`<div class="r-form-grid">${[0,1].map(i=>`<label class="r-field"><span>${i?'Second':'First'} driver</span><select data-q-compare="${i}">${ordered.map(d=>`<option value="${d.id}" ${ui.compare[i]===d.id?'selected':''}>${d.id} · ${esc(d.title)}</option>`).join('')}</select></label>`).join('')}</div>${a&&b?`<label class="f-criterion-picker"><span>Compare aspect</span><select id="q-compare-view">${[['scenario','Scenario'],['measurement','Measurement'],['rationale','Rationale & traceability']].map(([id,label])=>`<option value="${id}" ${ui.compareView===id?'selected':''}>${label}</option>`).join('')}</select></label><div class="q-comparison-scroll"><table class="q-comparison"><thead><tr><th>Compare</th><th>${a.id}</th><th>${b.id}</th></tr></thead><tbody>${[['Priority',d=>d.priority+' — '+d.rationale],['Stimulus',d=>d.stimulus],['Conditions',d=>d.conditions],['Response',d=>d.response],['Target',d=>d.metric+' · '+targetText(d)],['Measurement',d=>d.measurement+' · '+d.window],['Requirements',d=>d.requirementIds.join(', ')],['Responsibilities',d=>d.responsibilityIds.map(id=>projectResponsibilities(project).find(r=>r.id===id)?.title).join(', ')],['Candidate tactic',d=>d.tactic]].filter(([name])=>({scenario:['Stimulus','Conditions','Response'],measurement:['Target','Measurement'],rationale:['Priority','Requirements','Responsibilities','Candidate tactic']}[ui.compareView].includes(name))).map(([name,value])=>`<tr><th>${name}</th><td>${esc(value(a)||'Not recorded')}</td><td>${esc(value(b)||'Not recorded')}</td></tr>`).join('')}</tbody></table></div>`:'<p>Add two drivers to compare them.</p>'}`;
 return `<article class="r-card ${ui.section==='compare'?'f-quality-comparison':''}"><div class="r-card-head"><div><p class="r-kicker">Quality drivers / ${ui.section}</p><h2>${title}</h2></div>${button('add-conflict','Record a conflict')}</div>${body}</article>`;
}
function conflictList(){return project.quality.conflicts.map(c=>`<div class="q-conflict"><div><small>${c.id} · ${c.driverIds.join(' / ')}</small><h3>${esc(c.title)}</h3><p>${esc(c.effect)}</p><span class="r-badge ${conflictIsResolved(project,c)?'confirmed':'reference'}">${conflictIsResolved(project,c)?'Resolved':c.status==='resolved'?'Needs re-review':'Open conflict'}</span>${c.resolution?`<p><b>Resolution:</b> ${esc(c.resolution)}</p>`:''}</div><button class="r-btn" data-q-conflict="${c.id}">Review</button></div>`).join('')||'<p class="r-note">No conflicts recorded yet.</p>'}
function tradeoffList(d){const pairs=potentialTradeoffs(project,d);return pairs.map(t=>`<article class="q-tradeoff"><small>${t.driverIds.join(' / ')} · ${t.shared.map(id=>esc(projectResponsibilities(project).find(r=>r.id===id)?.title)).join(', ')}</small><h3>${esc(t.title)}</h3><p>${esc(t.detail)}</p>${t.existingId?`<button class="r-btn" data-q-conflict="${t.existingId}">Review recorded trade-off</button>`:`<button class="r-btn gold" data-q-tradeoff="${t.id}">Record for review</button>`}</article>`).join('')||'<p class="r-note">No potential trade-offs match the current responsibility links. This does not prove that none exist.</p>'}
function model(){return `<article class="r-card r-map-card q-map-card"><div class="r-card-head"><div><p class="r-kicker">Live model / Quality dependencies</p><h2>From intent to architectural impact</h2></div>${window.aiwChapterModels?.has?.(2)?`<button class="r-btn" data-cm-open="2" title="Return to this chapter's own architecture models">${icon('model')}Chapter 2 models</button>`:''}${button('wide',icon('model'),'icon-only','aria-label="'+(ui.wide?'Restore inspector beside map':'Widen canvas')+'"')}</div><div class="q-driver-strip" aria-label="Choose a quality driver">${orderedDrivers(project).map(d=>`<button data-q-select="${d.id}" data-q-insight="driver:${d.id}" aria-pressed="${ui.selected===d.id}" style="--q-color:${qualityType(d.category).color}"><small>${d.id}</small><b>${esc(d.title)}</b></button>`).join('')}</div><div class="q-map-tools"><div class="r-layer-buttons">${[['outcome','Outcomes'],['requirement','Requirements'],['driver','Scenarios'],['responsibility','Responsibilities']].map(([id,label])=>`<button data-q-layer="${id}" aria-pressed="${ui.layers.includes(id)}">${label}</button>`).join('')}</div><div class="r-map-actions">${button('focus',ui.focus?'Show all drivers':'Focus selected','','aria-pressed="'+ui.focus+'"')}${button('tradeoffs','Potential trade-offs','','aria-pressed="'+ui.tradeoffs+'"')}${button('flow',icon(ui.flow?'pause':'play')+(ui.flow?'Pause link trace':'Trace rationale'),'','aria-pressed="'+ui.flow+'"')}</div></div>${ui.ghost?ghostPanel():''}<div id="q-map-viewport" class="r-map-viewport" tabindex="0" aria-label="Quality driver map. Scroll to explore dependencies."><svg id="q-map" role="group" aria-label="Live quality driver map"></svg></div><div class="r-map-caption"><span>Green: dependency · Gold dashes: potential trade-off</span><span id="q-map-count"></span></div><p class="r-map-note">Outcomes motivate requirements; quality scenarios constrain responsibilities. Link tracing explains this rationale, not payment timing.</p></article>`}
function mapData(){
  const all=orderedDrivers(project),focus=selected(),pairs=ui.tradeoffs?potentialTradeoffs(project,ui.focus?focus:null):[],ids=new Set(ui.focus&&focus?[focus.id]:all.map(d=>d.id));
  for(const t of pairs)for(const id of t.driverIds)ids.add(id);
  let ds=all.filter(d=>ids.has(d.id));if(ui.ghost?.mode==='edit')ds=ds.map(d=>d.id===ui.ghost.target?{...d,...ui.ghost.record}:d);if(ui.ghost?.mode==='new')ds.push({...ui.ghost.record,id:'GHOST',scenarioId:'PROPOSED'});
  const map=new Map(),edges=[];const add=(kind,id,title,sub,record)=>map.set(kind+':'+id,{key:kind+':'+id,kind,id,title,sub,record});
  for(const d of ds){add('driver',d.id,d.title,d.id==='GHOST'?'Unsaved proposal':d.id+' / '+d.scenarioId,d);for(const id of d.requirementIds){const r=project.artefacts.find(a=>a.id===id);if(!r)continue;add('requirement',r.id,r.title,r.id,r);edges.push({from:'requirement:'+r.id,to:'driver:'+d.id,label:'drives'});for(const o of driverOutcomes(project,{...d,requirementIds:[r.id]})){add('outcome',o.id,o.title,o.id,o);edges.push({from:'outcome:'+o.id,to:'requirement:'+r.id,label:'motivates'})}}for(const id of d.responsibilityIds){const r=projectResponsibilities(project).find(n=>n.id===id);if(!r)continue;add('responsibility',r.id,r.title,'Application',r);edges.push({from:'driver:'+d.id,to:'responsibility:'+r.id,label:'constrains'})}}
  for(const t of pairs)edges.push({from:'driver:'+t.driverIds[0],to:'driver:'+t.driverIds[1],label:'potential trade-off',tradeoff:true});
  const ns=[...map.values()].filter(n=>ui.layers.includes(n.kind)),visible=new Set(ns.map(n=>n.key)),seen=new Set();return {nodes:ns,edges:edges.filter(e=>{const k=e.from+e.to+e.label;if(seen.has(k)||!visible.has(e.from)||!visible.has(e.to))return false;seen.add(k);return true})};
}
function wrapped(text,max){const words=text.split(/\s+/).flatMap(w=>w.match(new RegExp('.{1,'+max+'}','g'))||[]),rows=[];let row='';for(const w of words){if((row+' '+w).trim().length>max&&row){rows.push(row);row=w}else row=(row+' '+w).trim()}if(row)rows.push(row);return rows.slice(0,3).map((r,i)=>i===2&&rows.length>3?r.slice(0,max-1)+'…':r)}
function drawMap(){const svg=$('#q-map');if(!svg)return;const data=mapData(),view=$('#q-map-viewport'),mobile=matchMedia('(max-width:700px)').matches,groups=['outcome','requirement','driver','responsibility'].filter(g=>data.nodes.some(n=>n.kind===g)),w=mobile?Math.max(160,Math.min(244,view.clientWidth-90)):Math.max(150,Math.min(220,(view.clientWidth-48-(groups.length-1)*30)/Math.max(1,groups.length))),pos=new Map(),labels=[];let column=0,top=48;
  for(const kind of groups){const rows=data.nodes.filter(n=>n.kind===kind),x=mobile?20:24+column*(w+30);labels.push({kind,x,y:mobile?top-18:26,count:rows.length});rows.forEach((n,i)=>pos.set(n.key,{x,y:(mobile?top:52)+i*145}));if(mobile)top+=rows.length*145+38;column++}
  const width=mobile?view.clientWidth:Math.max(500,48+groups.length*w+Math.max(0,groups.length-1)*30),height=mobile?Math.max(340,top):Math.max(400,...[...pos.values()].map(n=>n.y+140));svg.setAttribute('viewBox',`0 0 ${width} ${height}`);svg.style.width=width+'px';svg.style.height=height+'px';
  const focus=ui.node||'driver:'+ui.selected,near=new Set([focus]);data.edges.filter(e=>e.from===focus||e.to===focus).forEach(e=>{near.add(e.from);near.add(e.to)});if(focus.startsWith('driver:')){const fd=data.nodes.find(n=>n.key===focus)?.record;if(fd)driverOutcomes(project,fd).forEach(o=>near.add('outcome:'+o.id))}
  svg.innerHTML=`<defs><marker id="q-arrow" markerWidth="8" markerHeight="8" refX="7" refY="4" orient="auto"><path class="q-marker" d="M1 1L7 4L1 7"/></marker></defs>${labels.map(l=>`${mobile?'':`<rect class="q-lane" x="${l.x-8}" y="8" width="${w+16}" height="${height-16}" rx="10"/>`}<text class="q-lane-title" x="${l.x}" y="${l.y}">${{outcome:'Outcomes',requirement:'Requirements',driver:'Quality scenarios',responsibility:'Responsibilities'}[l.kind]}</text>`).join('')}${data.edges.map(e=>{const a=pos.get(e.from),b=pos.get(e.to),active=(e.from===focus||e.to===focus)||(!e.tradeoff&&near.has(e.from)&&near.has(e.to));const path=mobile||a.x===b.x?`M${a.x+w} ${a.y+56} C${a.x+w+(mobile?60:24)} ${a.y+56},${b.x+w+(mobile?60:24)} ${b.y+56},${b.x+w} ${b.y+56}`:`M${a.x+w} ${a.y+56} C${a.x+w+20} ${a.y+56},${b.x-20} ${b.y+56},${b.x} ${b.y+56}`;return `<path class="q-edge ${active?'active':''} ${e.tradeoff?'tradeoff':''}" d="${path}" marker-end="url(#q-arrow)"><title>${esc(e.from+' '+e.label+' '+e.to)}</title></path>${ui.flow&&active&&!e.tradeoff?`<circle class="q-flow-dot" r="3"><animateMotion path="${path}" dur="2.5s" repeatCount="indefinite"/></circle>`:''}`}).join('')}${data.nodes.map(n=>{const a=pos.get(n.key),ghost=n.id==='GHOST'||ui.ghost?.target===n.id;return `<g class="q-node ${n.key===focus?'selected':''} ${near.has(n.key)?'related':'muted'} ${ghost?'ghost':''}" transform="translate(${a.x},${a.y})" role="button" tabindex="0" aria-label="${esc(n.sub+' '+n.title)}" aria-pressed="${n.key===focus}" data-q-node="${n.key}" data-q-insight="${n.key}"><title>${esc(n.title)}</title><rect width="${w}" height="115" rx="8"/><rect class="q-node-accent" width="4" height="50" y="27" style="fill:${n.kind==='driver'?qualityType(n.record.category).color:'#759065'}"/><text x="13" y="20" class="q-node-id">${esc(n.sub)}</text>${wrapped(n.title,Math.floor((w-26)/7.2)).map((line,i)=>`<text x="13" y="${42+i*17}" class="q-node-title">${esc(line)}</text>`).join('')}<text x="13" y="101" class="q-node-state">${ghost?'Unsaved proposal':n.kind==='driver'?esc(wrapped(targetText(n.record),Math.floor((w-26)/6))[0]):n.kind==='responsibility'?'Review impact':n.record.confirmed?'✓ Confirmed':'Unconfirmed source'}</text></g>`}).join('')}`;
  $('#q-map-count').textContent=data.nodes.length+' objects · '+data.edges.length+' links';$('#q-map-empty')?.remove();if(!data.nodes.length){const el=document.createElement('div');el.id='q-map-empty';el.className='r-empty';el.innerHTML='<h3>Reveal a perspective to see the model.</h3>';view.append(el)}
}
function ghostPanel(){const g=ui.ghost,old=g.target?driver(g.target):null,fields=old?['conditions','metric','unit','window','measurement','tactic'].filter(k=>old[k]!==g.record[k]):['title','response','metric'];return `<section class="r-ghost-bar" aria-label="Unsaved quality proposal"><div class="r-ghost-heading"><div><p class="r-kicker">Ghost / Unsaved proposal</p><h3>${esc(g.label)}</h3><span>${old?old.id+' retains its stable reference.':'A new quality scenario will be created.'}</span></div><div class="r-ghost-actions">${button('edit-ghost','Review & edit','gold')}${button('dismiss-ghost','Dismiss')}</div></div><details class="r-ghost-changes"><summary>Compare the proposed change</summary>${fields.map(k=>`<div><b>${esc(k[0].toUpperCase()+k.slice(1))}</b>${old?`<p><small>Current</small>${esc(old[k]||'Not recorded')}</p>`:''}<p class="proposed"><small>Proposed</small>${esc(g.record[k])}</p></div>`).join('')}</details></section>`}
function inspector(){const key=ui.node,d=selected();if(key&&!key.startsWith('driver:'))return contextInspector(key);const g=qualityGuidance(project,d,ui.tab),ps=qualityProposals(project,d,ui.tab);return `<header class="r-inspector-head"><span>${icon('cursor')}Driver lens</span><small>${ui.tab}</small></header><div class="r-inspector-body">${button('back-surface','Back to workspace','r-mobile-return')}${d?`<p class="r-kicker">${d.id} / ${d.scenarioId} · ${qualityType(d.category).name}</p><h2>${esc(d.title)}</h2>${badge(d)}<p>${esc(d.response||'Describe the expected response.')}</p><div class="q-measure-card"><small>${esc(d.metric||'Metric missing')}</small><strong>${esc(targetText(d))}</strong>${targetBadge(d)}<p>${esc(d.window||'Measurement window missing')}</p></div><div class="r-actions"><button class="r-btn primary" data-q-edit="${d.id}">${icon('edit')}Edit scenario</button>${button('compare-selected','Compare')}</div><dl><div><dt>Priority and reason</dt><dd>${d.priority} · ${esc(d.rationale||'Not recorded')}</dd></div><div><dt>Stimulus</dt><dd>${esc(d.stimulus||'Not recorded')}</dd></div><div><dt>Operating conditions</dt><dd>${esc(d.conditions||'Not recorded')}</dd></div><div><dt>How to verify</dt><dd>${esc(d.measurement||'Not recorded')}</dd></div><div><dt>Owner</dt><dd>${esc(d.owner||'Not recorded')}</dd></div><div><dt>Evidence / source</dt><dd>${esc(d.source||'Not recorded')}</dd></div><div><dt>Origin</dt><dd>${d.origin==='reference'?'Illustrative reference':d.origin==='suggestion'?'Guidance proposal':'User-authored'}</dd></div></dl>${sourceChanged(project,d)?'<div class="r-error">A source requirement changed. Revisit this scenario against the current requirement.</div>':''}<h3>Source requirements</h3><div class="q-link-list">${d.requirementIds.map(id=>{const a=project.artefacts.find(a=>a.id===id);return a?`<button data-q-context="requirement:${id}"><b>${id}</b> ${esc(a.title)}<small>${a.confirmed?'Confirmed':'Unconfirmed source'}</small></button>`:`<span class="r-error">${id} is missing</span>`}).join('')||'<p>No requirements linked.</p>'}</div><h3>Affected responsibilities</h3><div class="q-link-list">${d.responsibilityIds.map(id=>`<a href="/?chapter=4&object=${id}">${esc(projectResponsibilities(project).find(r=>r.id===id)?.title||id)} ${icon('arrow')}</a>`).join('')||'<p>No responsibilities linked.</p>'}</div><h3>Candidate tactic</h3><p>${esc(d.tactic||'Explore a tactic with Mind Factory.')}</p>`:`<h2>Define an expectation you can test.</h2><p>Start from the current requirements, then define the stimulus, conditions, response, and measurement.</p>`}${evidenceContextHTML(project,d?.id,ui.tab)}<div class="r-attention"><p class="r-kicker">A useful next thought</p><p>${esc(g.attention)}</p><small>${esc(g.next)}</small>${ps[0]?`<button class="r-btn gold" data-q-proposal="${ps[0].id}">${icon('spark')}Explore a ghost suggestion</button>`:''}</div>${d?`<h3>Potential trade-offs</h3>${tradeoffList(d)}`:''}</div>`}
function contextRecord(key){const [kind,id]=key.split(':');return kind==='driver'?driver(id):kind==='responsibility'?projectResponsibilities(project).find(n=>n.id===id):project.artefacts.find(a=>a.id===id)}
function contextDrivers(key){const [kind,id]=key.split(':');return orderedDrivers(project).filter(d=>kind==='requirement'?d.requirementIds.includes(id):kind==='responsibility'?d.responsibilityIds.includes(id):driverOutcomes(project,d).some(o=>o.id===id))}
function contextInspector(key){const a=contextRecord(key);if(!a){ui.node=null;return inspector()}const [kind,id]=key.split(':'),ds=contextDrivers(key);return `<header class="r-inspector-head"><span>${icon('cursor')}Context lens</span><small>${ui.tab}</small></header><div class="r-inspector-body">${button('back-surface','Back to workspace','r-mobile-return')}<p class="r-kicker">${kind} · ${id}</p><h2>${esc(a.title)}</h2><p>${esc(a.description)}</p>${a.acceptance?`<h3>Acceptance</h3><p>${esc(a.acceptance)}</p>`:''}${a.source?`<h3>Source / evidence</h3><p>${esc(a.source)}</p>`:''}<h3>Connected quality drivers</h3><div class="q-link-list">${ds.map(d=>`<button data-q-select="${d.id}"><b>${d.id}</b> ${esc(d.title)}<small>${esc(targetText(d))} · ${d.priority}</small></button>`).join('')}</div><div class="r-actions"><a class="r-btn" href="${kind==='responsibility'?'/?chapter=4&object='+id:'/?chapter=1&tab=work&artefact='+id}">Open source ${icon('arrow')}</a></div><div class="r-attention"><p>These ${ds.length} drivers depend on this ${kind}. Review their targets together when its behaviour changes.</p></div></div>`}
function validation(){const fs=qualityFindings(project),gaps=fs.filter(f=>f.level==='error'),shown=ui.filter==='all'?fs:ui.filter==='assumptions'?fs.filter(f=>f.level!=='error'):gaps;return `<article class="r-card"><div class="r-card-head"><div><p class="r-kicker">Quality ${project.quality.version} / Requirements ${project.contentVersion}</p><h2>Review what can be measured.</h2></div>${button('validate',icon('shield')+'Run checks','primary')}</div><p class="r-intro">Check target clarity, source links, evidence, and recorded conflicts. Findings remain visible in every handoff.</p><div class="r-validation-stats"><div><b>${gaps.length}</b><span>Content and conflict gaps</span></div><div><b>${fs.length-gaps.length}</b><span>Assumptions and review items</span></div></div><p class="r-review-state">${qualityReviewCurrent(project)?'Checks recorded for the current quality and requirements revisions.':'Changes require a fresh review.'} These checks do not certify the architecture.</p><div class="r-filter-tabs">${[['gaps','Content gaps'],['assumptions','Assumptions & review'],['all','All findings']].map(([id,label])=>`<button data-q-filter="${id}" aria-pressed="${ui.filter===id}">${label}</button>`).join('')}</div><div class="f-findings">${shown.map(f=>`<article class="r-finding"><span class="r-finding-icon ${f.level}">${f.level==='error'?'!':'○'}</span><div><small>${f.driverId}</small><h3>${esc(f.title)}</h3><p>${esc(f.detail)}</p></div><button class="r-btn" data-q-fix="${f.id}">Review ${icon('arrow')}</button></article>`).join('')||'<div class="r-empty"><h3>No findings in this category.</h3><p>Review the remaining categories before carrying the drivers forward.</p></div>'}</div></article>`}
function output(){const ds=orderedDrivers(project),fs=qualityFindings(project);return `<article class="r-card"><div class="r-card-head"><div><p class="r-kicker">Chapter 2 / Output</p><h2>The prioritised driver brief</h2></div><span class="r-badge ${qualityHandoffCurrent(project)?'confirmed':'draft'}">${qualityHandoffCurrent(project)?'Current handoff':'Working revision'}</span></div><p class="r-intro">${ds.length} quality drivers · ${ds.filter(d=>d.targetConfirmed).length} confirmed targets · ${fs.length} open findings.</p><div class="r-actions">${button('export-md',icon('file')+'Export driver register','primary')}${button('export-json',icon('file')+'Export shared project')}</div><p class="r-note">Named priority and explicit ordering determine this register. Candidate tactics remain proposals for Chapter 3.</p><div class="r-output-list">${ds.map((d,i)=>`<button data-q-select="${d.id}" data-q-insight="driver:${d.id}"><span><small>${i+1} · ${d.id} / ${d.scenarioId} · ${d.priority}</small><strong>${esc(d.title)}</strong><small>${esc(d.metric)} · ${esc(targetText(d))}</small></span>${targetBadge(d)}</button>`).join('')}</div><div class="r-handoff"><p class="r-kicker">What comes next / Chapter 03</p><h3>Carry the drivers into architectural decisions.</h3><p>Stable driver and scenario references, source requirements, candidate tactics, and open findings travel together.</p>${button('handoff',qualityHandoffCurrent(project)?'Open Chapter 3 decisions '+icon('arrow'):'Review & carry forward '+icon('arrow'),'gold')}</div></article>`}
function chapter3(){return `<article class="r-card q-receipt"><div class="r-card-head"><div><p class="r-kicker">Same project / No re-entry</p><h2>Quality drivers received</h2></div><span class="r-badge ${qualityHandoffCurrent(project)?'confirmed':'reference'}">${qualityHandoffCurrent(project)?'Current handoff':'Handoff needs review'}</span></div><p>${orderedDrivers(project).length} quality drivers are available using their original references. ${qualityFindings(project).length} current findings remain open.</p><div class="r-reference-note">This is the Chapter 3 receiving surface. Selecting and evaluating architectural decisions is the next chapter build.</div>${orderedDrivers(project).map(d=>`<details class="r-intake-record"><summary><span><small>${d.id} / ${d.scenarioId} · ${d.priority}</small><strong>${esc(d.title)}</strong></span>${targetBadge(d)}</summary><div><p>${esc(d.rationale)}</p><dl><div><dt>Stimulus</dt><dd>${esc(d.stimulus)}</dd></div><div><dt>Conditions</dt><dd>${esc(d.conditions)}</dd></div><div><dt>Response</dt><dd>${esc(d.response)}</dd></div><div><dt>Measure</dt><dd>${esc(d.metric)} · ${esc(targetText(d))}</dd></div><div><dt>Verification</dt><dd>${esc(d.measurement)} · ${esc(d.window)}</dd></div><div><dt>Requirements</dt><dd>${d.requirementIds.join(', ')}</dd></div><div><dt>Candidate tactic</dt><dd>${esc(d.tactic)}</dd></div></dl><a class="r-btn" href="/?chapter=2&tab=model&driver=${d.id}">Open source driver ${icon('arrow')}</a></div></details>`).join('')}<div class="r-actions"><a class="r-btn" href="/?chapter=2&tab=output">Review Chapter 2 output</a>${button('export-md','Export driver register')}</div></article>`}
function select(id,scroll=true){if(!driver(id))return;ui.selected=id;ui.node=null;hideTip();if(ui.tab==='work'&&ui.section==='intake')ui.section='scenarios';render();if(ui.tab!=='model'&&scroll)openContextPanel();if(ui.tab==='model')scrollToMapNode('driver:'+id)}
function scrollToMapNode(key){const el=$('#q-map [data-q-node="'+key+'"]'),view=$('#q-map-viewport');if(!el||!view)return;const r=el.getBoundingClientRect(),v=view.getBoundingClientRect();if(r.top<v.top+20||r.bottom>v.bottom-20)view.scrollTop+=r.top-v.top-Math.max(20,(v.height-r.height)/2);if(r.left<v.left||r.right>v.right)view.scrollLeft+=r.left-v.left-20}
function navigate(tab){ui.tab=tab;ui.flow=false;ui.node=null;render();$('.r-tabs .active')?.focus()}
function field(label,name,value,textarea=false,attrs=''){return `<label class="r-field" for="q-field-${name}"><span>${label}</span>${textarea?`<textarea id="q-field-${name}" name="${name}" rows="3" ${attrs.includes('maxlength')?'':'maxlength="4000"'} ${attrs}>${esc(value)}</textarea>`:`<input id="q-field-${name}" name="${name}" value="${esc(value)}" ${attrs.includes('maxlength')?'':'maxlength="4000"'} ${attrs}>`}</label>`}
function dialog(title,body,kind){if(presentAssistant(kind,title,body))return;ui.lastFocus=document.activeElement;ui.modal=kind;ui.dirty=false;ui.flow=false;hideTip();$('#q-dialog-host').innerHTML=`<dialog class="r-dialog q-dialog" aria-labelledby="q-dialog-title"><header><div><p class="r-kicker">Chapter 02 / ${ui.tab}</p><h2 id="q-dialog-title">${title}</h2></div>${button('close',icon('close'),'icon-only','aria-label="Close dialog"')}</header><div id="q-form-error" class="r-error" role="alert" hidden></div>${body}<div id="q-discard" class="r-discard" hidden><p>Discard your unsaved changes?</p>${button('keep-editing','Keep editing')}${button('discard','Discard changes')}</div></dialog>`;const el=$('.r-dialog');el.addEventListener('cancel',e=>{e.preventDefault();closeDialog()});refineAssistantDialog(el,kind);el.showModal();(el.querySelector('input:not([type=checkbox]),textarea,select')||el.querySelector('button')).focus()}
function closeDialog(force=false){if(ui.busy&&!force)return;if(ui.dirty&&!force){$('#q-discard').hidden=false;$('#q-discard button').focus();return}ui.modal=null;ui.dirty=false;$('.r-dialog')?.close();$('#q-dialog-host').innerHTML='';if(ui.lastFocus?.isConnected)ui.lastFocus.focus()}
function blankDriver(requirementId){return {category:'integrity',priority:'Important',operator:'At most',targetValue:'',requirementIds:requirementId?[requirementId]:[],responsibilityIds:requirementId&&project.artefacts.find(a=>a.id===requirementId)?.modelRef?[project.artefacts.find(a=>a.id===requirementId).modelRef]:[],title:'',stimulus:'',conditions:'',response:'',metric:'',unit:'',window:'',measurement:'',owner:'',source:'',rationale:'',tactic:'',confirmed:false,targetConfirmed:false,origin:'user'}}
function editDriver(id=null,proposal=null,requirementId=null,step=0,preset=null){const old=id?driver(id):null,d={...(proposal?.record||old||blankDriver(requirementId)),...(preset||{})};if(old&&sourceChanged(project,old))d.confirmed=false;formRecord={id:old?.id,origin:proposal?'suggestion':old?.origin||'user'};ui.step=step;dialog(proposal?'Review & edit the quality proposal':old?'Edit '+old.id:'Add a quality scenario',`<form id="q-driver-form"><nav class="q-form-steps" aria-label="Scenario editing steps">${['Scenario','Measurement','Traceability & priority'].map((label,i)=>`<button type="button" data-q-form-step="${i}" aria-pressed="${i===step}"><span>${i+1}</span>${label}</button>`).join('')}</nav><section data-q-panel="0" ${step!==0?'hidden':''}><div class="r-form-grid"><label class="r-field"><span>Quality concern</span><select name="category">${QUALITY_TYPES.map(t=>`<option value="${t.id}" ${d.category===t.id?'selected':''}>${t.name}</option>`).join('')}</select></label>${field('Driver title','title',d.title,false,'required maxlength="160"')}</div>${field('Stimulus — what happens?','stimulus',d.stimulus,true)}${field('Operating conditions','conditions',d.conditions,true)}${field('Expected response','response',d.response,true)}${button('form-next','Next: measurement '+icon('arrow'))}</section><section data-q-panel="1" ${step!==1?'hidden':''}><div class="r-reference-note">Numerical examples are editable assumptions. Confirm the metric and threshold against agreed evidence.</div>${field('Metric — what is measured?','metric',d.metric)}<div class="q-target-fields"><label class="r-field"><span>Comparator</span><select name="operator">${OPERATORS.map(o=>`<option ${d.operator===o?'selected':''}>${o}</option>`).join('')}</select></label>${field('Target value','targetValue',d.targetValue,false,'type="number" min="0" step="any"')}${field('Unit','unit',d.unit)}</div>${field('Measurement window / sample','window',d.window,true)}${field('How will this be verified?','measurement',d.measurement,true)}<label class="r-checkbox"><input name="targetConfirmed" type="checkbox" ${d.targetConfirmed?'checked':''}>I confirm this target against agreed evidence.</label>${button('form-next','Next: traceability & priority '+icon('arrow'))}</section><section data-q-panel="2" ${step!==2?'hidden':''}><fieldset class="q-choices"><legend>Source requirements</legend>${reqs().map(a=>`<label><input type="checkbox" name="requirementIds" value="${a.id}" ${d.requirementIds.includes(a.id)?'checked':''}><span><b>${a.id}</b> ${esc(a.title)}<small>${a.confirmed?'Confirmed':'Unconfirmed source'}</small></span></label>`).join('')||'<p>Add requirements in Chapter 1 first.</p>'}</fieldset><fieldset class="q-choices"><legend>Affected application responsibilities</legend>${projectResponsibilities(project).map(r=>`<label><input type="checkbox" name="responsibilityIds" value="${r.id}" ${d.responsibilityIds.includes(r.id)?'checked':''}><span>${esc(r.title)}</span></label>`).join('')}</fieldset><div class="r-form-grid"><label class="r-field"><span>Priority</span><select name="priority">${QUALITY_PRIORITIES.map(x=>`<option ${d.priority===x?'selected':''}>${x}</option>`).join('')}</select></label>${field('Owner','owner',d.owner)}</div>${field('Why this priority?','rationale',d.rationale,true)}${field('Source / target evidence','source',d.source,true)}${field('Candidate tactic — for evaluation','tactic',d.tactic,true)}<label class="r-checkbox"><input name="confirmed" type="checkbox" ${d.confirmed?'checked':''}>I have reviewed and confirm this scenario.</label><p class="r-note">${old?old.id+' / '+old.scenarioId+' remain unchanged.':'Stable driver and scenario IDs are assigned on save.'} Confirmation records your review; it does not approve a design.</p></section><div class="r-dialog-actions">${old?button('delete-driver','Remove driver','danger',`data-id="${old.id}"`):''}${button('close','Cancel')}<button type="submit" class="r-btn primary">${proposal?'Apply edited proposal':'Save scenario'}</button></div></form>`,'driver');formStep(step)}
function formStep(step){ui.step=Math.max(0,Math.min(2,step));document.querySelectorAll('[data-q-panel]').forEach(el=>el.hidden=Number(el.dataset.qPanel)!==ui.step);document.querySelectorAll('[data-q-form-step]').forEach(el=>el.setAttribute('aria-pressed',String(Number(el.dataset.qFormStep)===ui.step)));$('.r-dialog').scrollTop=0;$('[data-q-panel="'+ui.step+'"] input,[data-q-panel="'+ui.step+'"] textarea,[data-q-panel="'+ui.step+'"] select')?.focus()}
function editConflict(id=null,pair=null){const old=id?project.quality.conflicts.find(c=>c.id===id):null,c=old||{driverIds:pair?.driverIds||ui.compare,title:pair?.title||'',effect:pair?.detail||'',owner:'',resolution:'',status:'open'};const stale=old?.status==='resolved'&&!conflictIsResolved(project,old);dialog(old?'Review '+old.id:'Record a quality conflict',`<form id="q-conflict-form" data-id="${old?.id||''}"><p>Describe the competing expectations and how the project will resolve them.</p>${stale?'<div class="r-reference-note">A driver changed. Review the earlier resolution against the current targets.</div>':''}<div class="r-form-grid">${[0,1].map(i=>`<label class="r-field"><span>${i?'Second':'First'} driver</span><select name="driver${i}">${orderedDrivers(project).map(d=>`<option value="${d.id}" ${c.driverIds?.[i]===d.id?'selected':''}>${d.id} · ${esc(d.title)}</option>`).join('')}</select></label>`).join('')}</div>${field('Conflict title','title',c.title,false,'required maxlength="180"')}${field('Competing expectations / effect','effect',c.effect,true)}${field('Resolution and rationale','resolution',c.resolution,true)}<div class="r-form-grid">${field('Resolution owner','owner',c.owner)}<label class="r-field"><span>Resolution status</span><select name="status"><option value="open" ${c.status!=='resolved'||stale?'selected':''}>Open for review</option><option value="resolved" ${c.status==='resolved'&&!stale?'selected':''}>Resolved with rationale</option></select></label></div><div class="r-dialog-actions">${button('close','Cancel')}<button type="submit" class="r-btn primary">Save conflict review</button></div></form>`,'conflict')}
function preview(id){const p=qualityProposals(project,selected(),ui.tab).find(x=>x.id===id);if(!p){toast('That proposal is no longer relevant. Reopen Mind Factory.');return}closeDialog(true);ui.ghost=p;ui.tab='model';ui.node=null;ui.layers=['outcome','requirement','driver','responsibility'];render();$('.r-ghost-bar')?.scrollIntoView({block:'start'});toast('Unsaved preview. Review and edit before applying.')}
function contextMenu(kind){const a=contextRecord(ui.node),ds=contextDrivers(ui.node),[type,id]=ui.node.split(':');if(!a)return;const prompt={work:'Which connected scenario needs a clearer target?',model:'Which targets share this source or responsibility, and where might they compete?',validate:'Which source changes or unresolved findings affect these drivers?',output:'Which driver references should inform the next architectural decision?'}[ui.tab];dialog(kind==='sol'?'Sol · Act on this context':'Mind Factory · Explore this context',`<p>Chapter 2 / ${ui.tab} · ${esc(type+' '+id)}</p><h3>${esc(a.title)}</h3><div class="r-reference-note">${prompt}</div>${kind==='sol'?`<div class="r-actions"><a class="r-btn" href="${type==='responsibility'?'/?chapter=4&object='+id:'/?chapter=1&tab=work&artefact='+id}">Open source ${icon('arrow')}</a>${type==='requirement'?`<button type="button" class="r-btn" data-q-from-requirement="${id}">Add a linked scenario</button>`:''}</div>`:'<p>Compare the connected targets before selecting a tactic. Choose a driver to explore its editable ghost suggestions.</p>'}${ds.map(d=>`<article class="r-pattern"><h3>${d.id} · ${esc(d.title)}</h3><p>${esc(d.metric)} · ${esc(targetText(d))}</p>${kind==='mind'?`<p>${esc(d.tactic||'No candidate tactic is recorded yet.')}</p>`:''}<button type="button" class="r-btn" data-q-select="${d.id}">Explore ${d.id}</button></article>`).join('')}`,kind);}
function assistantMenu(kind){if(ui.node&&!ui.node.startsWith('driver:'))return contextMenu(kind);const d=selected(),g=qualityGuidance(project,d,ui.tab),ps=qualityProposals(project,d,ui.tab),context=ui.node&&!ui.node.startsWith('driver:')?contextRecord(ui.node):null;const actions={work:`${button('add','Add scenario')}${button('go-model','Explore the driver map')}${button('go-compare','Compare priorities')}`,model:`${button('flow',ui.flow?'Pause link trace':'Trace rationale')}${button('go-compare','Compare drivers')}${button('add-conflict','Record a conflict')}`,validate:`${button('run-checks-menu','Run checks','primary')}${button('go-work','Review scenarios')}`,output:`${button('export-md','Export driver register')}${button('export-json','Export shared project')}${button('handoff','Review handoff','gold')}`};if(kind==='sol')dialog('Sol · Act on this context',`${evidenceAssistantLink('sol')}<p>${context?esc(context.title):d?esc(d.id+' · '+d.title):'Quality drivers'} · ${ui.tab}</p><div class="r-reference-note">${esc(g.next)}</div><p>${esc(g.attention)}</p><div class="r-menu-actions">${actions[ui.tab]}${d?`<button class="r-btn" data-q-edit="${d.id}">Edit ${d.id}</button>`:''}</div>${ps[0]?`<h3>A useful next improvement</h3><p>${esc(ps[0].reason)}</p><button class="r-btn gold" data-q-proposal="${ps[0].id}">Preview editable ghost</button>`:''}`,'sol');else dialog('Mind Factory · Explore the implications',`${evidenceAssistantLink('mind')}<p>Chapter 2 / ${ui.tab} · ${d?esc(d.id):'Quality drivers'}</p><div class="r-reference-note">${{work:'Which operating condition would make this requirement harder to satisfy?',model:'Which responsibility carries the target, and which other target competes with it?',validate:'What evidence would make this target reproducible and the conflict resolvable?',output:'Which candidate tactic should Chapter 3 evaluate against this driver?'}[ui.tab]}</div>${ps.map(p=>`<article class="r-pattern"><h3>${esc(p.label)}</h3><p>${esc(p.reason)}</p><button class="r-btn gold" data-q-proposal="${p.id}">Preview on the model</button></article>`).join('')}<p class="r-note">Rule-based proposals remain editable. Live-generation status is shown in Sol.</p>`,'mind')}
function handoff(){if(ui.modal)closeDialog(true);if(qualityHandoffCurrent(project)){location.href=projectURL('/?chapter=3');return}const fs=qualityFindings(project);dialog('Carry quality drivers into decisions',`<form id="q-handoff-form"><p>${project.quality.drivers.length} driver and scenario references will be available in Chapter 3, with the same sources, targets, and responsibilities.</p><div class="r-reference-note">${fs.length} open findings travel with the project. Proposed tactics remain candidates.</div>${!qualityReviewCurrent(project)?`<p>Record validation for the current quality and requirements revisions first.</p>${button('go-validate','Go to validation','primary')}`:`${fs.length?'<label class="r-checkbox"><input type="checkbox" name="acknowledge" required>I acknowledge the open findings and will carry them forward.</label>':''}<div class="r-dialog-actions">${button('close','Cancel')}<button type="submit" class="r-btn primary">Continue to Chapter 3 ${icon('arrow')}</button></div>`}</form>`,'handoff')}
async function download(markdown=false){try{const file=await exportProject(2,markdown?'md':'json');toast('Export prepared · '+file.filename+' · '+file.bytes.toLocaleString()+' bytes.')}catch(e){toast(e.message)}}
function next(id=null){if(ui.chapter===3){location.href=projectURL('/?chapter=2');return}const m=qualityMilestones(project).find(m=>m.id===id)||qualityMilestones(project).find(m=>!m.done);if(!m){handoff();return}ui.tab=m.tab;if(m.section)ui.section=m.id==='priorities'?'priorities':m.section;ui.node=null;render();$('.r-surface')?.scrollIntoView({block:'start'})}
function hideTip(){clearTimeout(tipTimer);if($('#cursor-tip'))$('#cursor-tip').hidden=true}
function showTip(el,event){if(!ui.cursor||ui.modal||matchMedia('(max-width:700px)').matches||event?.pointerType==='touch')return;const key=el.dataset.qInsight,a=contextRecord(key);if(!a)return;clearTimeout(tipTimer);tipTimer=setTimeout(()=>{const isDriver=key.startsWith('driver:'),g=isDriver?qualityGuidance(project,a,ui.tab):null,tip=$('#cursor-tip');tip.className='r-cursor-tip';tip.innerHTML=`<small>CHAPTER 02 / ${ui.tab.toUpperCase()} · ${isDriver?a.id:key.split(':')[1]}</small><h3>${esc(a.title)}</h3><p>${esc(isDriver?g.explanation:a.description)}</p><p>${esc(isDriver?g.measurement:contextDrivers(key).length+' linked quality drivers')}</p><p class="r-tip-attention">${esc(isDriver?g.attention:'Select to inspect the linked drivers and their competing expectations.')}</p><small>${esc(isDriver?'Architectural implication: '+g.implication:'Changes to this source can affect the connected drivers.')}</small><small>${esc(isDriver?g.next:'Follow a driver to review its target.')} Select to explore editable ghosts.</small>`;tip.innerHTML+=`<small>${esc(evidenceCursorText(project,isDriver?a.id:key.split(':')[1]))}</small>`;tip.hidden=false;const box=el.getBoundingClientRect(),x=event?.clientX??box.x+box.width/2,y=event?.clientY??box.y+box.height/2;tip.style.left=Math.max(8,Math.min(innerWidth-328,x+14))+'px';tip.style.top=Math.max(8,Math.min(innerHeight-tip.offsetHeight-8,y+14))+'px'},250)}
document.addEventListener('click',async e=>{const b=e.target.closest('button,[data-q-node]');if(!b||b.disabled||ui.busy)return;
  if(b.dataset.qTab)return navigate(b.dataset.qTab);
  if(b.dataset.qSection){ui.section=b.dataset.qSection;ui.node=null;render();return}
  if(b.dataset.qSelect){if(ui.modal)closeDialog(true);return select(b.dataset.qSelect);}
  if(b.dataset.qEdit)return editDriver(b.dataset.qEdit);
  if(b.dataset.qFromRequirement)return editDriver(null,null,b.dataset.qFromRequirement);
  if(b.dataset.qMilestone)return next(b.dataset.qMilestone);
  if(b.dataset.qFormStep!==undefined)return formStep(Number(b.dataset.qFormStep));
  if(b.dataset.qProposal)return preview(b.dataset.qProposal);
  if(b.dataset.qConflict)return editConflict(b.dataset.qConflict);
  if(b.dataset.qTradeoff)return editConflict(null,potentialTradeoffs(project,null).find(t=>t.id===b.dataset.qTradeoff));
  if(b.dataset.qMove)return send('quality.move',{id:b.dataset.qMove,direction:b.dataset.direction},'Priority order saved.');
  if(b.dataset.qFilter){ui.filter=b.dataset.qFilter;render();return}
  if(b.hasAttribute('data-q-layers-all')){ui.layers=ui.layers.length===chapterPerspectives[2].length?[]:chapterPerspectives[2].map(l=>l[0]);ui.tab='model';ui.menu=false;render();return}
  if(b.dataset.qLayer){ui.tab='model';ui.menu=false;ui.layers=ui.layers.includes(b.dataset.qLayer)?ui.layers.filter(k=>k!==b.dataset.qLayer):[...ui.layers,b.dataset.qLayer];render();return}
  if(b.dataset.qContext){ui.node=b.dataset.qContext;$('#q-inspector').innerHTML=inspector();refineWorkspace(ui.tab,{chapter:2,id:ui.node?.split(':')[1]||ui.selected});return}
  if(b.dataset.qNode){const key=b.dataset.qNode;if(key==='driver:GHOST')return editDriver(null,ui.ghost);if(key.startsWith('driver:'))return select(key.split(':')[1]);ui.node=key;drawMap();$('#q-inspector').innerHTML=inspector();refineWorkspace(ui.tab,{chapter:2,id:ui.node?.split(':')[1]||ui.selected});hideTip();return}
  if(b.dataset.qFix){const f=qualityFindings(project).find(f=>f.id===b.dataset.qFix);if(!f)return;if(f.code==='intake'){ui.tab='work';ui.section='intake';render();return}if(f.code==='empty')return editDriver();if(f.code==='conflict')return editConflict(f.driverId);if(f.code==='source-confirmation'){ui.tab='work';ui.section='intake';render();return}ui.selected=f.driverId;return editDriver(f.driverId,null,null,['measurement','target-assumption'].includes(f.code)?1:['requirements','broken-requirement','responsibilities','priority','evidence','confirmation'].includes(f.code)?2:0)}
  const action=b.dataset.qAction;
  if(['go-model','go-work','go-compare','go-validate','run-checks-menu','flow'].includes(action)&&ui.modal)closeDialog(true);
  switch(action){
    case'reload':load();break;case'menu':ui.menu=!ui.menu;render();break;case'next':next();break;
    case'review-intake':await send('quality.intake',{},'Current requirements reviewed for Chapter 2.');break;
    case'add':editDriver();break;case'sol':assistantMenu('sol');break;case'mind':assistantMenu('mind');break;case'cursor':ui.cursor=!ui.cursor;saveCursorPreference(ui.cursor);render();break;
    case'go-model':navigate('model');break;case'go-work':ui.section='scenarios';navigate('work');break;case'go-compare':case'compare-selected':ui.compare=[ui.selected,orderedDrivers(project).find(d=>d.id!==ui.selected)?.id].filter(Boolean);ui.section='compare';navigate('work');break;case'go-validate':navigate('validate');break;
    case'focus':ui.focus=!ui.focus;render();break;case'tradeoffs':ui.tradeoffs=!ui.tradeoffs;render();break;case'flow':ui.flow=!ui.flow;render();break;case'wide':ui.wide=!ui.wide;render();break;
    case'edit-ghost':editDriver(ui.ghost.target||null,ui.ghost);break;case'dismiss-ghost':ui.ghost=null;render();toast('Proposal dismissed. The saved project is unchanged.');break;
    case'add-conflict':if(project.quality.drivers.length<2){toast('Add two drivers before recording a conflict.');break}editConflict();break;
    case'validate':case'run-checks-menu':ui.tab='validate';await send('quality.review',{},'Checks recorded for the current revisions.');break;
    case'handoff':handoff();break;case'export-md':download(true);break;case'export-json':download(false);break;
    case'back-surface':closeContextPanel();break;case'form-next':formStep(ui.step+1);break;
    case'close':closeDialog();break;case'keep-editing':$('#q-discard').hidden=true;break;case'discard':closeDialog(true);break;
    case'delete-driver':{const d=driver(b.dataset.id);dialog('Remove '+d.id+'?',`<p>${esc(d.title)}</p><p>This removes the driver, its scenario, and any recorded conflicts that reference it. Chapter 1 requirements remain available.</p><div class="r-dialog-actions">${button('close','Keep driver')}${button('confirm-delete','Remove driver','danger',`data-id="${d.id}"`)}</div>`,'delete');break}
    case'confirm-delete':await send('quality.delete',{id:b.dataset.id},'Quality driver removed.');break;
    case'refresh-conflict':try{project=(await store.load()).document;const el=$('#q-form-error');if(el)el.innerHTML='Latest project loaded. Your form values are preserved. Review them before saving again.';else render()}catch(e){toast(e.message)}break;
    case'about':dialog('Quality with a clear trail',`<p>Each quality driver contains one scenario with a stimulus, operating conditions, expected response, and measurable target.</p><p>Priorities use named tiers and explicit order. Trade-off prompts identify possible tension; recorded conflicts carry a resolution and owner.</p><p>Saved records belong to your private project. Requirement changes flag affected scenarios, and edits invalidate earlier validation and handoff records.</p><p>Cursor, Sol, and Mind Factory use project rules. There is no external LLM or live bank connection. Numerical reference targets require confirmation; candidate tactics are not approved decisions.</p>`,'about');break;
  }
});
document.addEventListener('submit',async e=>{if(!e.target.closest('.q-dialog'))return;e.preventDefault();const form=e.target,fd=new FormData(form),data=Object.fromEntries(fd);
  if(form.id==='q-driver-form'){data.requirementIds=fd.getAll('requirementIds');data.responsibilityIds=fd.getAll('responsibilityIds');data.confirmed=form.elements.confirmed.checked;data.targetConfirmed=form.elements.targetConfirmed.checked;data.id=formRecord.id;data.origin=formRecord.origin;await send('quality.driver',data,'Scenario saved with its stable driver reference.')}
  if(form.id==='q-conflict-form'){data.driverIds=[data.driver0,data.driver1];if(form.dataset.id)data.id=form.dataset.id;await send('quality.conflict',data,'Conflict review saved.')}
  if(form.id==='q-handoff-form'){if(await send('quality.handoff',{acknowledge:form.elements.acknowledge?.checked===true},'Quality drivers carried forward.'))location.href=projectURL('/?chapter=3');}
});
document.addEventListener('input',e=>{if(e.target.id==='q-search'){ui.query=e.target.value;$('#q-driver-list').innerHTML=driverList();refineWorkspace(ui.tab,{chapter:2,id:ui.node?.split(':')[1]||ui.selected});return}if(e.target.closest('.q-dialog form')){ui.dirty=true;const form=e.target.form;if(form?.id==='q-driver-form'){if(e.target.name!=='confirmed')form.elements.confirmed.checked=false;if(['metric','operator','targetValue','unit','window','measurement','conditions','response','stimulus','category','source','requirementIds','responsibilityIds'].includes(e.target.name))form.elements.targetConfirmed.checked=false}}});
document.addEventListener('change',e=>{if(e.target.id==='q-compare-view'){ui.compareView=e.target.value;render();$('#q-compare-view')?.focus({preventScroll:true});return}if(e.target.id==='q-category'){ui.category=e.target.value;$('#q-driver-list').innerHTML=driverList();refineWorkspace(ui.tab,{chapter:2,id:ui.node?.split(':')[1]||ui.selected})}if(e.target.dataset.qCompare!==undefined){const i=Number(e.target.dataset.qCompare);ui.compare[i]=e.target.value;if(ui.compare[0]===ui.compare[1])ui.compare[1-i]=orderedDrivers(project).find(d=>d.id!==e.target.value)?.id;render()}});
document.addEventListener('invalid',e=>{const panel=e.target.closest('[data-q-panel]');if(panel)formStep(Number(panel.dataset.qPanel))},true);
document.addEventListener('pointerover',e=>{const el=e.target.closest('[data-q-insight]');if(el)showTip(el,e)});document.addEventListener('pointerout',e=>{if(e.target.closest('[data-q-insight]'))hideTip()});document.addEventListener('focusin',e=>{const el=e.target.closest('[data-q-insight]');if(el)showTip(el)});document.addEventListener('focusout',hideTip);
document.addEventListener('keydown',e=>{if(e.key==='Escape')hideTip();const el=e.target.closest('#q-map [data-q-node]');if(el&&['Enter',' '].includes(e.key)){e.preventDefault();const key=el.dataset.qNode;el.dispatchEvent(new MouseEvent('click',{bubbles:true}));$('#q-map [data-q-node="'+key+'"]')?.focus({preventScroll:true})}});
window.addEventListener('resize',()=>{hideTip();clearTimeout(resizeTimer);resizeTimer=setTimeout(drawMap,150)});window.addEventListener('beforeunload',e=>{if(ui.dirty||ui.busy){e.preventDefault();e.returnValue=''}});
await load();

document.addEventListener('aiw:external-project',()=>{project=store.value.document;render();});
// The Chapter 2 models edit through this page's own editor and proposals.
window.aiwQualityPage={
  edit:id=>editDriver(id),
  add:category=>editDriver(null,null,null,0,category?{category}:null),
  tune:(id,preset)=>editDriver(id,null,null,preset&&preset.targetValue==null&&preset.priority?2:1,preset),
  propose(category){const pr=playbookDriverProposal(project,category);if(!pr?.record)return false;ui.ghost=pr;ui.node=null;render();toast('Unsaved preview. Review and edit before applying.');return true},
  focus(id){if(driver(id))ui.selected=id},
  get ghost(){return ui.ghost},get busy(){return ui.busy}
};
